//! Generated objects in the editor (docs/PROCEDURAL_DIRECTION.md §5.3, §6):
//! derived parts (`box_core::derived::Derived`) and their owners.
//!
//! - **Selection.** A click on a derived part selects its owner (through
//!   `prefab::editable_ancestor`, like prefab contents). Cmd + Alt + click
//!   (Ctrl + Alt elsewhere) on one inspects the part itself
//!   ([`EditorState::inspect_part`]): the selection is cleared, the part is
//!   outlined and the inspector shows a "Generated by" section (rule, key,
//!   a link to the owner) and its components.
//! - **Overrides** (docs/PROCEDURAL_DIRECTION.md §5.4). Editing a field of
//!   the inspected part writes an override into the owner's saved
//!   `Overrides` (one undo step; a drag is one step), and the rule's next
//!   pass applies it. Overridden fields are marked like a value that
//!   differs from its default (a dot, a brighter label) and their ↺ (or
//!   the label's Reset Override) removes the override. **Hide Part** (a
//!   button and the palette action `generated.hide_part`) hides the part;
//!   the owner's Generated section lists its overrides and hidden parts
//!   with Show and Reset. Transform and Name of a part are set by the rule
//!   and stay read-only.
//! - **Owner.** The inspector shows the owner's rule warnings (warning
//!   colour, one line each) under its header and a "Generated" section
//!   listing its parts by rule; a part's key inspects it.
//! - **Badges.** An owner with warnings has a warning glyph on its hierarchy
//!   row and next to it in the viewport; an owner row shows a gear and its
//!   part count. Both read [`GeneratedMarks`], rebuilt only when the world
//!   or the generated content changed (`GeneratedRevision`).

use std::collections::{BTreeMap, HashMap};

use box_core::derived::{Derived, GeneratedRevision, GeneratedWarnings, Preview};
use box_core::identity::Uid;
use box_core::prelude::{Entity, GlobalTransform};
use box_core::reflect::PartialReflect;
use box_engine::box_proc::overrides::{Overrides, covers};
use egui::{Align2, Pos2, Rect, Sense, Stroke, Ui, pos2, vec2};
use glam::Vec3;

use crate::state::EditorState;
use crate::theme::Tokens;

/// One owner of derived parts, as the hierarchy and viewport badges show it.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct OwnerMark {
    pub entity: Option<Entity>,
    /// Derived parts (all rules).
    pub parts: usize,
    /// Its rule warnings, one line each (`walls (end0): …`).
    pub warnings: Vec<String>,
}

/// Owners of derived parts by uid. Rebuilt when the world (edit, undo,
/// load, Play) or the generated content changed; cheap otherwise.
#[derive(Debug, Default)]
pub(crate) struct GeneratedMarks {
    owners: HashMap<Uid, OwnerMark>,
    /// (world generation, generated revision, entity count, playing).
    built: Option<(u64, u64, u32, bool)>,
}

impl EditorState {
    /// Rebuilds [`Self::generated_mark`]'s data when anything it depends on
    /// changed. Called once per frame.
    pub fn refresh_generated_marks(&mut self) {
        let revision = self
            .world
            .get_resource::<GeneratedRevision>()
            .map_or(0, |r| r.0);
        let key = (
            self.generation,
            revision,
            self.world.entity_count(),
            self.is_playing(),
        );
        if self.generated.built == Some(key) {
            return;
        }
        self.generated.built = Some(key);
        let mut owners: HashMap<Uid, OwnerMark> = HashMap::new();
        for d in self.world.query::<&Derived>().iter() {
            // A drawing tool's preview has no badges.
            if self.world.has::<Preview>(d.owner) {
                continue;
            }
            if let Some(u) = self.world.uid(d.owner) {
                let m = owners.entry(u).or_default();
                m.entity = Some(d.owner);
                m.parts += 1;
            }
        }
        for (e, u, w) in self
            .world
            .query::<box_core::world::Without<(Entity, &Uid, &GeneratedWarnings), &Preview>>()
            .iter()
        {
            let m = owners.entry(*u).or_default();
            m.entity = Some(e);
            m.warnings = w.0.iter().map(ToString::to_string).collect();
        }
        self.generated.owners = owners;
    }

    /// The derived parts and warnings of the owner `uid`, if it has any.
    pub fn generated_mark(&self, uid: Uid) -> Option<&OwnerMark> {
        self.generated.owners.get(&uid)
    }

    /// Shows the derived part `uid` read-only in the inspector (clearing
    /// the selection). False if `uid` is not a derived part.
    pub fn inspect_part(&mut self, uid: Uid) -> bool {
        let is_part = self
            .world
            .entity_by_uid(uid)
            .is_some_and(|e| self.world.has::<Derived>(e));
        if !is_part {
            return false;
        }
        self.select(None);
        self.inspected_part = Some(uid);
        true
    }

    /// The derived part the inspector shows, while it exists.
    pub fn inspected_part(&self) -> Option<Uid> {
        self.inspected_part
            .filter(|u| self.world.entity_by_uid(*u).is_some())
    }

    /// The owner, rule and role of the derived part `part`.
    fn part_address(&self, part: Uid) -> Option<(Entity, Uid, String, String)> {
        let e = self.world.entity_by_uid(part)?;
        let d = self.world.get::<Derived>(e)?;
        let owner_uid = self.world.uid(d.owner)?;
        Some((d.owner, owner_uid, d.rule.clone(), d.key.role().to_owned()))
    }

    /// The owner's saved overrides (empty without the component).
    pub fn overrides_of(&self, owner: Uid) -> Overrides {
        self.world
            .entity_by_uid(owner)
            .and_then(|e| self.world.get::<Overrides>(e).map(|o| (*o).clone()))
            .unwrap_or_default()
    }

    /// The overridden value (JSON text) of field `path` of the derived part
    /// `part`, if it has one.
    pub fn part_override(&self, part: Uid, path: &str) -> Option<String> {
        let (_, owner, rule, role) = self.part_address(part)?;
        self.overrides_of(owner)
            .field(&rule, &role, path)
            .map(str::to_owned)
    }

    /// Overrides field `path` (`WallGen.height`) of the derived part `part`
    /// with `value`: written to the owner's `Overrides` as one undo step
    /// (inside an open transaction it merges into it). False if `part` is
    /// not a derived part or the value cannot be stored.
    pub fn set_part_override(&mut self, part: Uid, path: &str, value: &dyn PartialReflect) -> bool {
        let Some((_, owner, rule, role)) = self.part_address(part) else {
            return false;
        };
        let Some(json) = self.override_json(part, path, value) else {
            return false;
        };
        let mut o = self.overrides_of(owner);
        o.set_field(&rule, &role, path, json);
        self.write_overrides(owner, o, &format!("Override {role} {path}"))
    }

    /// `value` as the JSON text of field `path` of `part` (applied over a
    /// copy of the current value, so dynamic values serialize as the field's
    /// type).
    fn override_json(&self, part: Uid, path: &str, value: &dyn PartialReflect) -> Option<String> {
        let e = self.world.entity_by_uid(part)?;
        let fp = self.world.field_path(path).ok()?;
        let mut current = self.world.get_field(e, &fp).ok()?;
        if let Err(err) = box_core::reflect::replace(current.as_mut(), value) {
            tracing::warn!("override {path}: {err}");
            return None;
        }
        match self.world.registry().value_to_json(current.as_ref()) {
            Ok(j) => Some(tidy_json(j).to_string()),
            Err(err) => {
                tracing::warn!("override {path}: {err}");
                None
            }
        }
    }

    /// Removes the override of `path` (and fields below it) on `part`: the
    /// rule's value comes back. One undo step; false if there was none.
    pub fn reset_part_override(&mut self, part: Uid, path: &str) -> bool {
        let Some((_, owner, rule, role)) = self.part_address(part) else {
            return false;
        };
        let mut o = self.overrides_of(owner);
        if !o.reset_field(&rule, &role, path) {
            return false;
        }
        self.finish_edit();
        self.write_overrides(owner, o, &format!("Reset Override {role} {path}"))
    }

    /// Edit ▸ Hide Generated Part: hides the inspected (or given) derived
    /// part with an override on its owner (one undo step) and selects the
    /// owner, whose Generated section can show it again.
    pub fn hide_part(&mut self, part: Uid) -> bool {
        let Some((_, owner, rule, role)) = self.part_address(part) else {
            return false;
        };
        let mut o = self.overrides_of(owner);
        o.set_hidden(&rule, &role, true);
        self.finish_edit();
        let ok = self.write_overrides(owner, o, &format!("Hide Part {role}"));
        if ok {
            self.select(Some(owner));
        }
        ok
    }

    /// Shows a hidden part again (one undo step).
    pub fn show_part(&mut self, owner: Uid, rule: &str, role: &str) -> bool {
        let mut o = self.overrides_of(owner);
        if !o.is_hidden(rule, role) {
            return false;
        }
        o.set_hidden(rule, role, false);
        self.finish_edit();
        self.write_overrides(owner, o, &format!("Show Part {role}"))
    }

    /// Removes every override of one part (one undo step).
    pub fn reset_part_overrides(&mut self, owner: Uid, rule: &str, role: &str) -> bool {
        let mut o = self.overrides_of(owner);
        if !o.reset_part(rule, role) {
            return false;
        }
        self.finish_edit();
        self.write_overrides(owner, o, &format!("Reset Overrides {role}"))
    }

    /// Writes the owner's `Overrides` (adding the component, or removing
    /// it when empty) through the edit stack: one undo step, or part of the
    /// open transaction.
    fn write_overrides(&mut self, owner: Uid, new: Overrides, label: &str) -> bool {
        if self.is_playing() {
            tracing::warn!("{label}: stop Play first (overrides are saved scene data)");
            return false;
        }
        let Some(e) = self.world.entity_by_uid(owner) else {
            return false;
        };
        let opened = !self.edits.is_open();
        if opened {
            self.begin_edit(label);
        }
        let has = self.world.has::<Overrides>(e);
        let ok = match (has, new.is_empty()) {
            (true, true) => {
                let r = self
                    .edits
                    .remove_component(&mut self.world, owner, "Overrides");
                self.report(label, r).is_some()
            }
            (true, false) => self.set_field(owner, "Overrides", &new),
            (false, false) => {
                let r = self
                    .edits
                    .add_component(&mut self.world, owner, "Overrides", Some(&new));
                self.report(label, r).is_some()
            }
            (false, true) => true,
        };
        if ok {
            self.changed(false);
        }
        if opened && self.inspector_edit.is_none() {
            self.finish_edit();
        }
        ok
    }
}

/// The owner's rule warnings, one line each in the warning colour (under
/// the inspector header, before the components).
pub(crate) fn owner_warnings_ui(ui: &mut Ui, state: &EditorState, e: Entity, t: &Tokens) {
    let Some(w) = state.world.get::<GeneratedWarnings>(e).map(|w| w.0.clone()) else {
        return;
    };
    for warning in &w {
        warning_line(ui, &warning.to_string(), t);
    }
    ui.add_space(4.0);
}

fn warning_line(ui: &mut Ui, text: &str, t: &Tokens) {
    ui.horizontal(|ui| {
        ui.add_space(t.pad_x + 4.0);
        let (r, _) = ui.allocate_exact_size(vec2(14.0, 16.0), Sense::hover());
        crate::feedback::warn_glyph(ui.painter(), r.center(), t);
        ui.add(egui::Label::new(egui::RichText::new(text).color(t.warn)).wrap());
    });
}

/// The derived parts of `owner` grouped by rule: (rule, [(uid, role)]).
fn parts_by_rule(state: &EditorState, owner: Entity) -> BTreeMap<String, Vec<(Uid, String)>> {
    let world = &state.world;
    let mut by_rule: BTreeMap<String, Vec<(Uid, String)>> = BTreeMap::new();
    for c in world.children(owner) {
        if let (Some(d), Some(u)) = (world.get::<Derived>(c), world.uid(c))
            && d.owner == owner
        {
            by_rule
                .entry(d.rule.clone())
                .or_default()
                .push((u, d.key.role().to_owned()));
        }
    }
    by_rule
}

/// The "Generated" section of an owner: its parts by rule, each key a link
/// that inspects the part. Nothing for an entity without parts.
pub(crate) fn generated_section_ui(ui: &mut Ui, state: &mut EditorState, e: Entity, t: &Tokens) {
    let by_rule = parts_by_rule(state, e);
    let owner = state.world.uid(e);
    let overrides = state
        .world
        .get::<Overrides>(e)
        .map(|o| (*o).clone())
        .unwrap_or_default();
    if by_rule.is_empty() && overrides.is_empty() {
        return;
    }
    let id = egui::Id::unique("box_editor_generated_open");
    let mut open = ui.ctx().data(|d| d.get_temp::<bool>(id)).unwrap_or(true);
    let total: usize = by_rule.values().map(Vec::len).sum();
    let title = format!(
        "Generated  ·  {total} part{}",
        if total == 1 { "" } else { "s" }
    );
    let mut inspect = None;
    let mut action: Option<OverrideAction> = None;
    crate::widgets::section_with_menu(
        ui,
        &title,
        Some(
            "Parts rules made from this entity's settings. They are rebuilt when the \
             settings change and are not saved. Cmd+Alt+click one in the viewport \
             (Ctrl+Alt elsewhere), or click its key here, to inspect it and override \
             its fields.",
        ),
        &mut open,
        None::<fn(&mut Ui)>,
        |ui| {
            for p in &overrides.parts {
                let what = match (p.hidden, p.fields.len()) {
                    (true, 0) => "hidden".to_owned(),
                    (true, n) => format!("hidden, {n} field{}", if n == 1 { "" } else { "s" }),
                    (false, n) => format!("{n} field{} overridden", if n == 1 { "" } else { "s" }),
                };
                crate::widgets::field_row(
                    ui,
                    "Override",
                    0.0,
                    Some("Saved on this entity; the rule's next pass applies it"),
                    |ui| {
                        ui.horizontal_wrapped(|ui| {
                            ui.label(egui::RichText::new(&p.part).font(t.mono()).color(t.text))
                                .on_hover_text(format!(
                                    "rule `{}`{}",
                                    p.rule,
                                    p.fields
                                        .iter()
                                        .map(|f| format!("\n{} = {}", f.path, f.value))
                                        .collect::<String>()
                                ));
                            ui.label(egui::RichText::new(what).color(t.text_weak));
                            if p.hidden
                                && ui
                                    .small_button("Show")
                                    .on_hover_text("Build this part again")
                                    .clicked()
                            {
                                action = Some(OverrideAction::Show(p.rule.clone(), p.part.clone()));
                            }
                            if ui
                                .small_button("Reset")
                                .on_hover_text("Remove every override of this part")
                                .clicked()
                            {
                                action =
                                    Some(OverrideAction::Reset(p.rule.clone(), p.part.clone()));
                            }
                        });
                    },
                );
            }
            for (rule, parts) in &by_rule {
                crate::widgets::field_row(ui, "Rule", 0.0, None, |ui| {
                    ui.label(
                        egui::RichText::new(format!(
                            "{rule}  ·  {} part{}",
                            parts.len(),
                            if parts.len() == 1 { "" } else { "s" }
                        ))
                        .color(t.text),
                    );
                });
                crate::widgets::field_row(ui, "Parts", 0.0, None, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.spacing_mut().item_spacing.x = 6.0;
                        for (uid, role) in parts.iter().take(MAX_LISTED) {
                            let r = ui
                                .add(
                                    egui::Label::new(
                                        egui::RichText::new(role)
                                            .font(t.mono())
                                            .color(t.accent_text),
                                    )
                                    .sense(Sense::click()),
                                )
                                .on_hover_text("Inspect this part (read-only)");
                            if r.clicked() {
                                inspect = Some(*uid);
                            }
                        }
                        if parts.len() > MAX_LISTED {
                            ui.label(
                                egui::RichText::new(format!(
                                    "and {} more",
                                    parts.len() - MAX_LISTED
                                ))
                                .color(t.text_weak),
                            );
                        }
                    });
                });
            }
        },
    );
    ui.ctx().data_mut(|d| d.insert_temp(id, open));
    if let Some(uid) = inspect {
        state.inspect_part(uid);
    }
    if let (Some(a), Some(owner)) = (action, owner) {
        match a {
            OverrideAction::Show(rule, part) => state.show_part(owner, &rule, &part),
            OverrideAction::Reset(rule, part) => state.reset_part_overrides(owner, &rule, &part),
        };
    }
}

/// Numbers that are exactly an `f32` written in the `f32`'s shortest form
/// (`3.4`, not `3.4000000953674316`): reflected `f32` fields go through
/// `f64` in JSON, and the saved text should read as typed.
fn tidy_json(v: serde_json::Value) -> serde_json::Value {
    use serde_json::Value as J;
    match v {
        J::Number(n) => match n.as_f64() {
            Some(x) if n.is_f64() && f64::from(x as f32) == x => {
                let short: f64 = (x as f32).to_string().parse().unwrap_or(x);
                serde_json::Number::from_f64(short).map_or(J::Number(n), J::Number)
            }
            _ => J::Number(n),
        },
        J::Array(a) => J::Array(a.into_iter().map(tidy_json).collect()),
        J::Object(o) => J::Object(o.into_iter().map(|(k, v)| (k, tidy_json(v))).collect()),
        other => other,
    }
}

/// An override's JSON text for display: numbers to 3 decimals.
fn short_json(text: &str) -> String {
    fn walk(v: &serde_json::Value, out: &mut String) {
        use serde_json::Value as J;
        match v {
            J::Number(n) if n.is_f64() => {
                let s = format!("{:.3}", n.as_f64().unwrap_or(0.0));
                out.push_str(s.trim_end_matches('0').trim_end_matches('.'));
            }
            J::Array(a) => {
                out.push('[');
                for (i, x) in a.iter().enumerate() {
                    if i > 0 {
                        out.push_str(", ");
                    }
                    walk(x, out);
                }
                out.push(']');
            }
            other => out.push_str(&other.to_string()),
        }
    }
    match serde_json::from_str::<serde_json::Value>(text) {
        Ok(v) => {
            let mut s = String::new();
            walk(&v, &mut s);
            s
        }
        Err(_) => text.to_owned(),
    }
}

enum OverrideAction {
    Show(String, String),
    Reset(String, String),
}

/// Keys listed per rule in the Generated section.
const MAX_LISTED: usize = 24;

/// The inspector for a derived part: read-only. "Generated by" (rule, key,
/// owner link), the part's warnings, and its components with disabled
/// controls.
pub(crate) fn part_inspector_ui(ui: &mut Ui, state: &mut EditorState, uid: Uid, t: &Tokens) {
    let Some(e) = state.world.entity_by_uid(uid) else {
        return;
    };
    let Some(d) = state.world.get::<Derived>(e).map(|d| (*d).clone()) else {
        return;
    };
    let owner_uid = state.world.uid(d.owner);
    let owner_name = state.display_name(d.owner);
    let (r, _) = ui.allocate_exact_size(vec2(ui.available_width(), 28.0), Sense::hover());
    ui.painter().text(
        pos2(r.left() + t.pad_x + 8.0, r.center().y),
        Align2::LEFT_CENTER,
        state.display_name(e),
        t.strong(),
        t.text_strong,
    );
    let (r, _) = ui.allocate_exact_size(vec2(ui.available_width(), 20.0), Sense::hover());
    ui.painter().text(
        pos2(r.left() + t.pad_x + 8.0, r.center().y),
        Align2::LEFT_CENTER,
        "Generated part  ·  edits become overrides",
        t.small(),
        t.text_weak,
    );
    let mut hide = false;
    ui.horizontal(|ui| {
        ui.add_space(t.pad_x + 4.0);
        hide = ui
            .button("Hide Part")
            .on_hover_text(
                "Do not build this part (an override on the owner; its Generated section \
                 shows it again)",
            )
            .clicked();
    });
    ui.add_space(6.0);

    let mut select_owner = false;
    let id = egui::Id::unique("box_editor_generated_by_open");
    let mut open = ui.ctx().data(|d| d.get_temp::<bool>(id)).unwrap_or(true);
    crate::widgets::section_with_menu(
        ui,
        "Generated by",
        Some("Which rule made this part, from which entity. Edit the owner to change it."),
        &mut open,
        None::<fn(&mut Ui)>,
        |ui| {
            crate::widgets::field_row(ui, "Rule", 0.0, None, |ui| {
                ui.label(egui::RichText::new(&d.rule).color(t.text));
            });
            crate::widgets::field_row(
                ui,
                "Key",
                0.0,
                Some("Stable and semantic: the owner's uid and the part's role"),
                |ui| {
                    ui.label(
                        egui::RichText::new(d.key.role())
                            .font(t.mono())
                            .color(t.text),
                    )
                    .on_hover_text(d.key.as_str());
                },
            );
            crate::widgets::field_row(ui, "Owner", 0.0, None, |ui| {
                if ui
                    .link(egui::RichText::new(&owner_name).color(t.accent_text))
                    .on_hover_text("Select the owner (edit it to change this part)")
                    .clicked()
                {
                    select_owner = true;
                }
            });
        },
    );
    ui.ctx().data_mut(|d| d.insert_temp(id, open));
    let warnings: Vec<String> = state
        .world
        .get::<GeneratedWarnings>(d.owner)
        .map(|w| {
            w.0.iter()
                .filter(|x| x.key.as_ref() == Some(&d.key))
                .map(|x| x.message.clone())
                .collect()
        })
        .unwrap_or_default();
    if !warnings.is_empty() {
        ui.add_space(4.0);
        for w in &warnings {
            warning_line(ui, w, t);
        }
    }
    let fields: Vec<(String, String)> = state
        .world
        .get::<Overrides>(d.owner)
        .and_then(|o| {
            o.part(&d.rule, d.key.role()).map(|p| {
                p.fields
                    .iter()
                    .map(|f| (f.path.clone(), f.value.clone()))
                    .collect()
            })
        })
        .unwrap_or_default();
    let overrides: Vec<String> = fields.iter().map(|(p, _)| p.clone()).collect();
    let mut part_ops: Vec<PartOp> = Vec::new();
    // The part's overrides, each with Reset (like a prefab's overrides).
    if !fields.is_empty() {
        let oid = egui::Id::unique("box_editor_part_overrides_open");
        let mut open = ui.ctx().data(|d| d.get_temp::<bool>(oid)).unwrap_or(true);
        crate::widgets::section_with_menu(
            ui,
            &format!("Overrides  ·  {}", fields.len()),
            Some("Values that replace the rule's for this part, saved on the owner"),
            &mut open,
            None::<fn(&mut Ui)>,
            |ui| {
                for (path, value) in &fields {
                    let field = path.split_once('.').map_or(path.as_str(), |(_, f)| f);
                    crate::widgets::field_row(ui, field, 0.0, Some(path), |ui| {
                        ui.horizontal(|ui| {
                            if ui
                                .small_button("Reset")
                                .on_hover_text("Remove this override: back to the rule's value")
                                .clicked()
                            {
                                part_ops.push(PartOp::Reset(path.clone()));
                            }
                            let shown: String = short_json(value).chars().take(32).collect();
                            ui.label(egui::RichText::new(shown).font(t.mono()).color(t.text))
                                .on_hover_text(value);
                        });
                    });
                }
            },
        );
        ui.ctx().data_mut(|d| d.insert_temp(oid, open));
    }
    for section in crate::inspect::entity_sections(&state.world, e) {
        let sid = egui::Id::unique(("box_editor_part_open", section.component));
        let mut open = ui.ctx().data(|d| d.get_temp::<bool>(sid)).unwrap_or(true);
        let title = crate::inspect::friendly_name(section.component);
        // Set by the rule itself, not part components: never overridden.
        let editable = !matches!(section.component, "Transform" | "Name" | "Uid");
        let tip = if editable {
            format!("{}: edit a field to override it", section.component)
        } else {
            format!("{}: set by the rule", section.component)
        };
        crate::widgets::section_with_menu(
            ui,
            &title,
            Some(&tip),
            &mut open,
            None::<fn(&mut Ui)>,
            |ui| {
                for row in &section.rows {
                    let overridden = editable && overrides.iter().any(|p| covers(&row.path, p));
                    part_row_ui(ui, state, row, t, editable, overridden, &mut part_ops);
                }
            },
        );
        ui.ctx().data_mut(|d| d.insert_temp(sid, open));
    }
    for op in part_ops {
        match op {
            PartOp::Set(path, value) => {
                // A drag or typing is one undo step: the transaction stays
                // open while this field is edited.
                let key = format!("Overrides:{uid}:{path}");
                if state.inspector_edit.as_deref() != Some(key.as_str()) || !state.edits.is_open() {
                    state.begin_edit(format!("Override {} {path}", d.key.role()));
                    state.inspector_edit = Some(key);
                }
                state.set_part_override(uid, &path, value.as_ref());
            }
            PartOp::Reset(path) => {
                state.reset_part_override(uid, &path);
            }
        }
    }
    // Close a continuous override edit once nothing is dragged or typed.
    let idle = ui.input(|i| !i.pointer.any_down()) && ui.ctx().memory(|m| m.focused().is_none());
    if idle && state.inspector_edit.is_some() {
        state.finish_edit();
    }
    if hide {
        state.hide_part(uid);
    } else if select_owner && let Some(u) = owner_uid {
        state.select(Some(u));
    }
}

/// What a part's field row asked for.
enum PartOp {
    /// Override the field with this value.
    Set(String, box_core::reflect::Value),
    /// Remove the field's override.
    Reset(String),
}

/// A field of an inspected part: the inspector's control; an edit becomes
/// an override, an overridden field is marked and its ↺ resets it.
fn part_row_ui(
    ui: &mut Ui,
    state: &mut EditorState,
    row: &crate::inspect::FieldRow,
    t: &Tokens,
    editable: bool,
    overridden: bool,
    out: &mut Vec<PartOp>,
) {
    use crate::panes::inspector::Op;
    let label = crate::panes::inspector::row_label(row);
    let doc = row.meta.as_ref().and_then(|m| m.doc);
    let mark = crate::widgets::RowMark {
        modified: overridden,
        ..Default::default()
    };
    let mut ops = Vec::new();
    let resp = ui
        .add_enabled_ui(editable, |ui| {
            crate::widgets::field_row_ex(ui, &label, row.depth as f32 * 12.0, doc, mark, |ui| {
                crate::panes::inspector::field_control(ui, state, row, t, &mut ops)
            })
            .1
        })
        .inner;
    if resp.revert {
        out.push(PartOp::Reset(row.path.clone()));
    }
    resp.label.context_menu(|ui| {
        if ui
            .add_enabled(overridden, egui::Button::new("Reset Override"))
            .on_disabled_hover_text("This field has the rule's value")
            .clicked()
        {
            out.push(PartOp::Reset(row.path.clone()));
            ui.close();
        }
    });
    for op in ops {
        match op {
            Op::Set { path, value, .. } => out.push(PartOp::Set(path, value)),
            Op::SwitchVariant {
                path,
                current,
                variant,
            } => match crate::inspect::switch_variant(
                state.world.registry(),
                current.as_ref(),
                variant,
            ) {
                Some(v) => out.push(PartOp::Set(path, v)),
                None => tracing::warn!("cannot switch {path} to {variant}"),
            },
            // Reset to default, copy, paste and the rest are not part edits.
            _ => {}
        }
    }
}

/// Warning badges next to owners with rule warnings, in the viewport: a
/// warning glyph and the count; hover lists the warnings, a click selects
/// the owner. Positions follow the camera each frame (a projection per
/// owner with warnings); the owner list comes from [`GeneratedMarks`].
pub(crate) fn warning_badges(ui: &Ui, rect: Rect, state: &mut EditorState, t: &Tokens) {
    let Some(view) = state.gizmo_view() else {
        return;
    };
    let mut badges: Vec<(Uid, Pos2, usize, String)> = Vec::new();
    for (uid, m) in &state.generated.owners {
        if m.warnings.is_empty() {
            continue;
        }
        let Some(gt) = m.entity.and_then(|e| state.world.get::<GlobalTransform>(e)) else {
            continue;
        };
        let Some(s) = view.project(Vec3::from(gt.0.translation)) else {
            continue;
        };
        let at = rect.min + vec2(s.x, s.y) + vec2(14.0, -14.0);
        if rect.contains(at) {
            badges.push((*uid, at, m.warnings.len(), m.warnings.join("\n")));
        }
    }
    badges.sort_by_key(|b| b.0);
    let p = ui.painter_at(rect);
    let mut select = None;
    for (uid, at, n, text) in badges {
        let badge = Rect::from_center_size(at, vec2(if n > 1 { 34.0 } else { 22.0 }, 20.0));
        p.rect_filled(badge, egui::CornerRadius::same(10), t.overlay_bg);
        p.rect_stroke(
            badge,
            egui::CornerRadius::same(10),
            Stroke::new(1.0, t.warn),
            egui::StrokeKind::Inside,
        );
        let glyph = if n > 1 {
            badge.left_center() + vec2(11.0, 0.0)
        } else {
            badge.center()
        };
        crate::feedback::warn_glyph(&p, glyph, t);
        if n > 1 {
            p.text(
                badge.right_center() - vec2(7.0, 0.0),
                Align2::RIGHT_CENTER,
                n.to_string(),
                t.strong_small(),
                t.warn,
            );
        }
        let r = ui
            .interact(
                badge,
                ui.scope_id().with(("gen_badge", uid)),
                Sense::click(),
            )
            .on_hover_text(text);
        if r.clicked() {
            select = Some(uid);
        }
    }
    if let Some(u) = select {
        state.select(Some(u));
    }
}

/// A small gear: the hierarchy's hint that a row has derived parts.
pub(crate) fn gear_glyph(p: &egui::Painter, c: Pos2, color: egui::Color32) {
    for k in 0..6 {
        let a = k as f32 * std::f32::consts::TAU / 6.0;
        let d = vec2(a.cos(), a.sin());
        p.line_segment([c + d * 3.0, c + d * 5.2], Stroke::new(1.6, color));
    }
    p.circle_stroke(c, 3.2, Stroke::new(1.3, color));
}
